('water', 'Žlebský vodopád', 'Vodopád v Česku.', 50.0918, 16.9107, 'CZ', 'wikidata-nature-cz-sk-waterfall', 10000, null, 'Q123191096', '{"en": {"description": "Waterfall in Czechia."}, "de": {"description": "Wasserfall in Tschechien."}, "pl": {"description": "Wodospad w Czechach."}, "nl": {"description": "Waterval in Tsjechië."}, "es": {"description": "Cascada en Chequia."}, "fr": {"description": "Cascade en Tchéquie."}, "uk": {"description": "Водоспад у Чехії."}}')
) as v(category, name, description, lat, lng, country, source, sort_order,
       image_url, wikidata_id, translations)
where not exists (
  select 1 from public.points_of_interest p
   where p.lat between v.lat - 0.00225 and v.lat + 0.00225
     and p.lng between v.lng - 0.0035 and v.lng + 0.0035
     and ( -- dvojník: stejný normalizovaný název do ~250 m
           (p.norm_name = public.poi_norm_name(v.name)
            and 111320.0 * sqrt(power(p.lat - v.lat, 2)
                + power((p.lng - v.lng) * cos(radians(v.lat)), 2)) <= 250)
        or -- cokoli prakticky na stejném pixelu
           (111320.0 * sqrt(power(p.lat - v.lat, 2)
                + power((p.lng - v.lng) * cos(radians(v.lat)), 2)) <= 40)
     )
);
